import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a fullness bonus: tight leftover space is preferred,
    and among near-equal leftovers, bins that are already fuller win."""
    bins = np.asarray(bins, dtype=float)
    cap = float(bins.max())
    if cap <= 0.0:
        return np.zeros_like(bins)
    residual = (bins - item) / cap            # normalised leftover after placing item
    fill_before = 1.0 - bins / cap            # how full each bin already is
    # Leftover dominates; fullness breaks near-ties and discourages opening new bins.
    score = -residual + 0.3 * fill_before ** 2
    return np.nan_to_num(score, nan=-1e9, posinf=1e9, neginf=-1e9)

import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with normalised leftovers and a bonus for near-perfect fits."""
    cap = float(np.max(bins))  # an empty bin is always present, so this is the capacity
    if cap <= 0:
        return np.zeros_like(bins, dtype=float)
    leftover = (bins - item) / cap          # normalised space left after placing item
    score = -leftover                        # best-fit core: smaller leftover is better
    # Strong bonus for almost perfect fits (waste below 2% of capacity)
    score = score + 1.0 * (leftover < 0.02)
    # Mild penalty for opening a fresh bin when partially filled bins fit
    empty = bins >= cap - 1e-12
    if np.any(~empty):
        score = score - 0.05 * empty
    return score.astype(float)

